g":"diveglobal"},{"q":"Is Statia a liveaboard destination?","a":"No - it''s a shore-and-day-boat heritage-dive island. Liveaboards may route past Statia on St. Kitts itineraries, but there is no Statia-based liveaboard - book a resort-and-dive-centre trip.","source":"bluewaterdivetravel.com","si_tag":"diveglobal"}],"seo":{"meta_title":"Sint Eustatius (Statia) Travel Guide: Heritage Diving, The Quill & Fort Oranje","meta_description":"Plan Sint Eustatius (Statia) - the Caribbean''s living underwater museum: 36+ dive sites over 18th-century cannons and anchors in a marine park bigger than the island, award-topping macro, the Quill rainforest volcano and historic Oranjestad.","slug":"sint-eustatius","primary_keyword":"Sint Eustatius Statia diving","long_tail":["Statia diving STENAPA marine park","The Quill volcano hike","Sint Eustatius blue beads","Fort Oranje Oranjestad","best macro diving Caribbean","Golden Rock Dive Center"],"search_language":"nl","local_keywords":["Statia","Sint Eustatius","The Quill","Mazinga","Oranjestad","Fort Oranje","STENAPA","Golden Rock","blauwe kralen"],"hreflang":["en","nl"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-30"},"booking":{"bin":"freely_bookable","level":"L1","codes":[],"consent_flow":false,"note":"Statia (Dutch special municipality) US L1, low crime; USD currency; IN the hurricane belt (Jun-Nov, peak Aug-Oct); serious medical routes to St. Maarten"},"si_checklist_25":{"run_date":"2026-07-30","hits":5,"misses":17,"disregarded":3,"note":"Canonical 25-SI list; Dive Liveaboards is a hard MISS (routes-through, not Statia-based); Tropical/Romance limited (not a beach node); sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"diveglobal","name":"diveglobal","status":"live","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"},{"si":"globaladv","name":"adventure","status":"live","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"},{"si":"hiking","name":"Hiking & Trails","status":"future"},{"si":"culture","name":"culture","status":"future","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"},{"si":"deepdive","name":"deepdive","status":"future","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW"}],"ultra":[{"name":"A private heritage-dive + Quill week (private DM + guide)","why_ultra":"the reefs, wrecks and macro to yourself with a private divemaster + a private Quill crater day + an Oranjestad heritage walk (no ultra-resort inventory on-island)","earning":"dive-op/DMC","virtuoso_value_add":false,"mor":"commissionable","tier":"luxury","price_band":"on application"},{"name":"A macro-photography specialty week","why_ultra":"a private guide reading the reef for macro + the blue-bead sites, with photo coaching - a connoisseur niche","earning":"dive-op","virtuoso_value_add":false,"mor":"commissionable","tier":"luxury","price_band":"on application"},{"name":"A private SXM-Statia air + island curator day","why_ultra":"a seamless Winair connection + a private guide across dive, volcano and Golden-Rock history","earning":"DMC + air","virtuoso_value_add":false,"mor":"commissionable","tier":"luxury","price_band":"on application"}],"source_verified":"2026-07-30","hero":{"query":"Sint Eustatius, Sint Eustatius"},"geo":{"lat":17.49,"lng":-62.98}}'::jsonb, 61),
